-- Ink-saving FROZEN HUB logo for FrozenHub 1 (20) and FrozenHub 2 (23).
-- psql "$DATABASE_URL" -f scripts/sql/frozenhub-logo-live-apply.sql
BEGIN;
CREATE TABLE "_bak_logo_Settings" AS SELECT * FROM "Settings" WHERE "TenantId" IN (20,23) AND "Key" ILIKE '%LOGO%';
UPDATE "Settings" SET "Value"='data:image/png;base64,', "UpdatedAt"=now() WHERE "TenantId" IN (20,23) AND "Key"='LOGO_BASE64_DATA_URI';
SELECT "TenantId","Key",length("Value") FROM "Settings" WHERE "TenantId" IN (20,23) AND "Key" ILIKE '%LOGO%';
COMMIT;

